  // ------------------------------------------------------------ Region settings help (CD-8)
  'rs.not_in_query': 'not in the query',
  'rpt.report_settings': 'Report settings',
  'rpt.save_report_settings': 'Save report settings',
  'rs.no_position_alert': 'The report has no `lat`/`lng` or `location` columns, so the map area can\'t filter it.',
  'rs.facets_help': 'Checkboxes list the most frequent values (Exclude lets users filter them out instead). Ranges and From/to need a number or date column: ranges are `from..to = label` separated by `;`, an open end left empty (`..1000`, `2020-01-01..`); a range includes its start, not its end. A star rating offers "4 stars and up" and so on (up to 5; `"max"` in the JSON changes it).',
  'rs.facets_help_chart': 'Chart: a bar or pie chart of the counts under the facet (collapsed); a bar or slice filters on its value.',
  'rs.calendar_help': 'The query returns `start_date`, `title` and optionally `end_date` (dates for all-day events, timestamps for events with a time).',
  'rs.chart_help': 'The first column is the label; each following numeric column is a series (up to 8). A Gantt chart reads `label, start, end` (dates or timestamps; an empty end is a milestone) and optional columns named `progress` (0 to 100), `task_id` and `depends_on` (the ids a task waits for, e.g. `3,4`).',
  'rs.map_help': 'Each row is a marker at `lat`, `lng` (or `location` as "lat,lng"), with `title` and `body` in its popup; a `geojson` column draws lines and areas (with PostGIS installed, a `geometry` or `geography` column in WGS 84 works too). A heat map weighs each place by a `weight` column.',
  'rs.tree_help': 'The query returns `id`, `parent_id` and `label` (and optionally `icon`); rows whose parent isn\'t in the result are the roots.',
  'rs.workflow_help': 'Workflows come from workflow definitions (Shared Components); application SQL starts them with `meta.start_workflow(…)`.',
  'rs.task_help': 'Tasks come from task definitions (Shared Components); application SQL creates them with `meta.create_task(…)`.',
